function C:setSticky()
  local status = StatusManager:GetStatus("DayIndex")
  local status2 = StatusManager:GetStatus("DayPart")
  local status3 = StatusManager:GetStatus("Follower")
  if status < 5 and status > 0 then
    if status2 < 2 then
      self.Aim.Value = NgoEx.SystemTextFromType("System_CollectNeta", Settings.CurrentLanguage.Value)
    else
      self.Aim.Value = NgoEx.SystemTextFromType("System_NightHint", Settings.CurrentLanguage.Value)
    end
  elseif status <= 10 then
    self.Aim.Value = NgoEx.SystemTextFromType("Sticky_aim10", Settings.CurrentLanguage.Value)
  elseif status <= 20 then
    self.Aim.Value = NgoEx.SystemTextFromType("Sticky_aim20", Settings.CurrentLanguage.Value)
  elseif status <= 30 then
    if status3 >= 1000000 then
      self.Aim.Value = NgoEx.SystemTextFromType("Sticky_life", Settings.CurrentLanguage.Value)
    else
      self.Aim.Value = NgoEx.SystemTextFromType("Sticky_aim30", Settings.CurrentLanguage.Value)
    end
  end
end

function C:FetchDayEvent()
  if not coroutine.isyieldable() then spawn(C.FetchDayEvent, self) return end
  self:setSticky()
  local day = StatusManager:GetStatus("DayIndex")
  if self.isGedatsu and day ~= 30 then
    return
  end
  UniTask.Delay(2700, false, "Update", nil, false)
  if not self.isTestScene and day == 1 then
    return
  end
  if self.nowEnding == "Ending_Completed" and day ~= 1 then
    local eventName = ("Ending_Completed_Day" .. TOSTR(day))
    spawn(function() self:AddEvent_2(eventName) end)
    return
  end
  if NetaManager.usedAlpha:Exists(function(al) return al.alphaType == "Angel" and al.level == 6 end) then
    spawn(function() self:AddEvent_1("Ending_DarkAngel") end)
    return
  end
  repeat
    local __sw3 = day
    if __sw3 == 3 then
      spawn(function() self:AddEvent_1("Scenario_Yachin") end)
      return
    elseif __sw3 == 5 then
      spawn(function() self:AddEvent_1("Event_Wishlist_day1") end)
      return
    elseif __sw3 == 6 then
      if self.wishlist ~= 0 then
        repeat
          local __sw4 = self.wishlist
          if __sw4 == 1 then
            spawn(function() self:AddEvent_1("Event_Wishlist_day2_1") end)
          elseif __sw4 == 2 then
            spawn(function() self:AddEvent_1("Event_Wishlist_day2_2") end)
          elseif __sw4 == 3 then
            spawn(function() self:AddEvent_1("Event_Wishlist_day2_3") end)
          else
            spawn(function() self:AddEvent_1("Event_Wishlist_day2_4") end)
          end
        until true
        return
      end
    end
  until true
  if day == 16 and self.isHearTrauma then
    spawn(function() self:AddEvent_1("YamiHi_SukiHi_3") end)
    return
  end
  repeat
    local __sw5 = day
    if __sw5 == 20 then
      spawn(function() self:AddEvent_1("Event_Day20") end)
      return
    elseif __sw5 == 24 then
      if StatusManager:GetStatus("Love") >= 80 then
        self:ExecuteActionConfirmed("OdekakeZikka", "OdekakeZikka", true)
        return
      end
    end
  until true
  if not self.isHorror and day == 27 and StatusManager:GetStatus("Follower") >= 500000 then
    self.isShurokued = true
    spawn(function() self:AddEvent_1("Event_MV_shuroku") end)
    return
  end
  if day == 29 and self.isShurokued then
    spawn(function() self:AddEvent_1("Event_MV_koukai") end)
    return
  end
  if day == 30 then
    self:chooseMaturo()
    return
  end
  if StatusManager:GetStatus("Stress") >= 80 and not self.isWristCut and self.beforeWristCut then
    self.isWristCut = true
    spawn(function() self:AddEvent_1("Status_Stress1_Day") end)
    return
  end
  if not self.isWristCut and StatusManager:GetStatus("Stress") >= 80 and StatusManager:GetMaxStatus("Stress") == 100 then
    self.beforeWristCut = true
  else
    self.beforeWristCut = false
  end
  if self.isWristCut and not self.isHakkyo and StatusManager:GetStatus("Stress") == 100 then
    self.isHakkyo = true
    self:SetShortcutState(false, 0.4)
    TaskbarManager:SetTaskbarInteractive(false)
    spawn(function() self:AddEvent_1("Status_Stress2_Day") end)
    return
  end
  local status = StatusManager:GetStatus("Stress")
  if day == 25 and self.isHakkyo and status >= 80 then
    spawn(function() self:AddEvent_1("Scenario_horror_day1_day") end)
    self.isHorror = true
    return
  end
  if day == 26 and self.isHorror then
    spawn(function() self:AddEvent_1("Scenario_horror_day2_day") end)
    return
  end
  if day == 27 and self.isHorror then
    spawn(function() self:AddEvent_1("Scenario_horror_day3_day") end)
    return
  end
  if day == 28 and self.isHorror then
    spawn(function() self:AddEvent_1("Scenario_horror_day4_day") end)
    return
  end
  if day == 29 and self.isHorror then
    spawn(function() self:AddEvent_1("Scenario_horror_day5_day") end)
    return
  end
  local status2 = StatusManager:GetStatus("Follower")
  if status2 >= 10000 and not NetaManager.GotAlpha:Exists(function(al) return al.alphaType == "Angel" and al.level == 1 end) then
    spawn(function() self:AddEvent_1("Scenario_Angel1") end)
  elseif status2 >= 30000 and not NetaManager.GotAlpha:Exists(function(al) return al.alphaType == "PR" and al.level == 1 end) then
    spawn(function() self:AddEvent_1("Scenario_PR1") end)
  elseif status2 >= 100000 and not NetaManager.GotAlpha:Exists(function(al) return al.alphaType == "Angel" and al.level == 2 end) then
    spawn(function() self:AddEvent_1("Scenario_Angel2") end)
  elseif status2 >= 250000 and not NetaManager.GotAlpha:Exists(function(al) return al.alphaType == "Angel" and al.level == 3 end) then
    spawn(function() self:AddEvent_1("Scenario_Angel3") end)
  elseif status2 >= 500000 and not NetaManager.GotAlpha:Exists(function(al) return al.alphaType == "Angel" and al.level == 4 end) then
    spawn(function() self:AddEvent_1("Scenario_Angel4") end)
  elseif status2 >= 1000000 and not NetaManager.GotAlpha:Exists(function(al) return al.alphaType == "Angel" and al.level == 5 end) and not NetaManager.usedAlpha:Exists(function(al) return al.alphaType == "Angel" and al.level == 6 end) and not self.isHakkyo then
    spawn(function() self:AddEvent_1("Scenario_Angel5") end)
