function C:FetchNightEvent()
  if self.isHorror or self.nowEnding == "Ending_Completed" or self.nowEnding ~= "Ending_None" then
    return
  end
  self:setSticky()
  local status = StatusManager:GetStatus("DayIndex")
  if not self.isTestScene and status == 1 then
    spawn(function() self:AddEvent_1("Scenario_loop1_day0_night") end)
  elseif self.isWristCut and self.beforeWristCut then
    self:SetShortcutState(false, 0.4)
    self.beforeWristCut = false
    spawn(function() self:AddEvent_1("Status_Stress1_Night") end)
  elseif self.isHakkyo and StatusManager:GetMaxStatus("Stress") == 100 then
    self.shortcuts.interactable = false
    self.shortcuts.blocksRaycasts = false
    self.shortcuts.alpha = 0.4
    StatusManager:UpdateStatusMaxToNumber("Stress", 120)
    spawn(function() self:AddEvent_1("Status_Stress2_Night") end)
  else
    if self.isHorror then
      return
    end
    if StatusManager:GetStatus("Stress") >= 120 then
      spawn(function() self:AddEvent_1("Ending_Stressful") end)
      return
    end
    if StatusManager:GetStatus("Yami") == 0 then
      spawn(function() self:AddEvent_1("Ending_Healthy") end)
      return
    end
    if StatusManager:GetStatus("Love") == StatusManager:GetMaxStatus("Love") then
      spawn(function() self:AddEvent_1("Ending_Sukisuki") end)
      return
    end
    if (StatusManager:GetStatus("Yami") == StatusManager:GetMaxStatus("Yami") and Random.Range(0, 100) == 66) or (Settings.mitaEnd:Distinct():ToList().Count >= 16 and StatusManager:GetStatus("Yami") == StatusManager:GetMaxStatus("Yami") and Random.Range(0, 20) == 6) then
      spawn(function() self:AddEvent_1("Ending_Megaten") end)
      return
    end
    if StatusManager:GetStatus("Love") == 0 then
      spawn(function() self:AddEvent_1("Ending_Ntr") end)
      return
    end
    if self.psycheCount >= 5 and not self.isGedatsu then
      self.nowEnding = "Ending_Meta"
      spawn(function() self:AddEvent_1("Ending_Meta") end)
      return
    end
    self:FetchUzagarami()
    if not self.isTestScene and status == 2 then
      spawn(function() self:AddEvent_1("Scenario_loop1_day1_night") end)
    end
  end
end

function C:FetchDialog()
