    else
      spawn(function() self:AddEvent_1("Event_Uzagarami_Dokuhaku") end)
    end
  end
end

function C:FetchScenarioEvent()
  if self.isHorror then
    return false
  end
  if self.nowEnding == "Ending_Completed" then
    return false
  end
  local status = StatusManager:GetStatus("DayIndex")
  local status2 = StatusManager:GetStatus("Follower")
  local status3 = StatusManager:GetStatus("Love")
  StatusManager:GetMaxStatus("Love")
  local status4 = StatusManager:GetStatus("Yami")
  StatusManager:GetMaxStatus("Yami")
  StatusManager:GetMaxStatus("Stress")
  if status == 8 and status2 < 10000 then
    spawn(function() self:AddEvent_1("Scenario_Yachin_Aseri") end)
    return true
  end
  repeat
    local __sw6 = status
    if __sw6 == 10 then
      if status2 >= 10000 then
        self:AddEventQueue_1("NightKaiwaSeparator")
        spawn(function() self:AddEvent_1("Scenario_Achieved_Aim") end)
      else
        spawn(function() self:AddEvent_1("Ending_Jikka") end)
      end
      return true
    elseif __sw6 == 14 then
      if status2 >= 100000 then
        spawn(function() self:AddEvent_1("Scenario_start_follower_high") end)
        self.isJuncho = true
      else
        spawn(function() self:AddEvent_1("Scenario_start_follower_low") end)
        self.isJuncho = false
      end
    end
  until true
  if status == 15 then
    if status3 >= 60 and status4 >= 60 then
      self.isHearTrauma = true
      spawn(function() self:AddEvent_1("Event_LongLine") end)
      spawn(function() self:AddEvent_1("Scenario_trauma_bimyou") end)
    else
      self.isHearTrauma = false
      spawn(function() self:AddEvent_1("Event_Dialog") end)
    end
  end
  repeat
    local __sw7 = status
    if __sw7 == 17 then
      if status2 > 250000 then
        self.isJuncho = true
      end
      if status4 >= 60 then
        self.isHappaOK = true
        if self.isJuncho then
          if status3 >= 60 then
            self:AddEventQueue_1("NightKaiwaSeparator")
            spawn(function() self:AddEvent_1("Scenario_happa_yamitoraikeike") end)
          else
            self:AddEventQueue_1("NightKaiwaSeparator")
            spawn(function() self:AddEvent_1("Scenario_happa_yamihateikeike") end)
          end
        elseif status3 >= 60 then
          self:AddEventQueue_1("NightKaiwaSeparator")
          spawn(function() self:AddEvent_1("Scenario_happa_yamitora") end)
        else
          self:AddEventQueue_1("NightKaiwaSeparator")
          spawn(function() self:AddEvent_1("Scenario_happa_yamihate") end)
        end
      else
        self.isHappaOK = false
        if self.isJuncho then
          if status3 >= 60 then
            self:AddEventQueue_1("NightKaiwaSeparator")
            spawn(function() self:AddEvent_1("Scenario_happa_kentoraikeike") end)
          else
            self:AddEventQueue_1("NightKaiwaSeparator")
            spawn(function() self:AddEvent_1("Scenario_happa_kenhateikeike") end)
          end
        elseif status3 >= 60 then
          self:AddEventQueue_1("NightKaiwaSeparator")
          spawn(function() self:AddEvent_1("Scenario_happa_kentora") end)
        else
          self:AddEventQueue_1("NightKaiwaSeparator")
          spawn(function() self:AddEvent_1("Scenario_happa_kenhate") end)
        end
      end
      return true
    elseif __sw7 == 22 then
      if status2 >= 250000 then
        self:AddEventQueue_1("NightKaiwaSeparator")
        spawn(function() self:AddEvent_1("Scenario_topstreamer_yadakenjoikeike") end)
      elseif status4 >= 60 then
        self:AddEventQueue_1("NightKaiwaSeparator")
        spawn(function() self:AddEvent_1("Scenario_topstreamer_trahappa") end)
      else
        self:AddEventQueue_1("NightKaiwaSeparator")
        spawn(function() self:AddEvent_1("Scenario_topstreamer_trakenjo") end)
      end
      return true
    elseif __sw7 == 23 then
      self:setLoveDiaryId(status3)
    end
  until true
  if status == 23 and status3 >= 80 then
    spawn(function() self:AddEvent_1("Scenario_jikka") end)
    return true
  end
  if status == 27 then
    if status2 >= 1000000 then
      if status3 >= 80 then
        if status4 >= 60 then
          if self.isJuncho then
            self:AddEventQueue_1("NightKaiwaSeparator")
            spawn(function() self:AddEvent_1("Scenario_topstreamer_trahappaikeike") end)
          else
            self:AddEventQueue_1("NightKaiwaSeparator")
            spawn(function() self:AddEvent_1("Scenario_topstreamer_trahappaikeikeatonobi") end)
          end
        elseif self.isJuncho then
          self:AddEventQueue_1("NightKaiwaSeparator")
          spawn(function() self:AddEvent_1("Scenario_topstreamer_trakenjoikeike") end)
        else
          self:AddEventQueue_1("NightKaiwaSeparator")
          spawn(function() self:AddEvent_1("Scenario_topstreamer_trakenjoikeikeatonobi") end)
        end
      elseif self.isJuncho then
        self:AddEventQueue_1("NightKaiwaSeparator")
        spawn(function() self:AddEvent_1("Scenario_topstreamer_yadahappakeike") end)
      else
        self:AddEventQueue_1("NightKaiwaSeparator")
        spawn(function() self:AddEvent_1("Scenario_topstreamer_yadahappakeikeatonobi") end)
      end
      return true
    end
    if status2 >= 500000 then
      self:AddEventQueue_1("NightKaiwaSeparator")
      spawn(function() self:AddEvent_1("Scenario_topstreamer_yadahappa") end)
      return true
    end
    self:AddEventQueue_1("NightKaiwaSeparator")
    spawn(function() self:AddEvent_1("Scenario_topstreamer_yadakenjo") end)
    return true
  end
  if not self.isOpenGinga and NetaManager.usedAlpha:Exists(function(al) return al.alphaType == "Kaidan" and al.level == 5 end) then
    self:AddEventQueue_1("NightKaiwaSeparator")
    spawn(function() self:AddEvent_1("Event_OpenGinga") end)
    return true
  end
  if status2 >= 1500000 and not self.is150mil then
    spawn(function() self:AddEvent_1("Event_150mil") end)
    self.is150mil = true
    return true
  end
  if status2 >= 3000000 and not self.is300mil then
    spawn(function() self:AddEvent_1("Event_300mil") end)
    self.is300mil = true
    return true
  end
  if status2 >= 5000000 and not self.is500mil then
    spawn(function() self:AddEvent_1("Event_500mil") end)
    self.is500mil = true
    return true
  end
  if status2 >= 9999999 then
    spawn(function() self:AddEvent_1("Ending_Ideon") end)
    return true
  end
  if self.isHorror then
    return false
  end
  repeat
    local __sw8 = Random.Range(0, 100)
    if __sw8 == 0 then
      spawn(function() self:AddEvent_1("Event_jinsei0") end)
      return true
    elseif __sw8 == 1 then
      spawn(function() self:AddEvent_1("Event_jinsei1") end)
      return true
    elseif __sw8 == 2 then
      spawn(function() self:AddEvent_1("Event_jinsei2") end)
      return true
    elseif __sw8 == 3 then
      spawn(function() self:AddEvent_1("Event_jinsei3") end)
      return true
    elseif __sw8 == 4 then
      spawn(function() self:AddEvent_1("Event_jinsei4") end)
      return true
    elseif __sw8 == 5 then
      if not StatusManager.isTodayHaishined then
        spawn(function() self:AddEvent_1("Event_Nerarenai_Night") end)
        return true
      end
    end
  until true
  return false
end

function C:chooseMaturo()
  self:SetShortcutState(false, 0.4)
  local status = StatusManager:GetStatus("Follower")
  local status2 = StatusManager:GetStatus("Love")
  local status3 = StatusManager:GetStatus("Yami")
  self:AddEventQueue_1("EndingSeparator")
  if self.isGedatsu then
    StatusManager:UpdateStatusToNumber("DayPart", 3)
    spawn(function() self:AddEvent_1("Ending_Kyouso") end)
  elseif status >= 1000000 and status3 >= 80 and status2 >= 80 and NetaManager.usedAlpha:Exists(function(al) return al.alphaType == "Angel" and al.level == 5 end) then
    spawn(function() self:AddEvent_1("Ending_Grand") end)
  elseif status >= 1000000 and status2 >= 80 then
    spawn(function() self:AddEvent_1("Ending_Happy") end)
  elseif status >= 500000 and status2 >= 80 then
    spawn(function() self:AddEvent_1("Ending_Normal") end)
  elseif status >= 500000 then
    spawn(function() self:AddEvent_1("Ending_Yarisute") end)
  elseif status3 >= 60 and status2 >= 60 then
    spawn(function() self:AddEvent_1("Ending_Needy") end)
  elseif status3 >= 60 then
    spawn(function() self:AddEvent_1("Ending_Sucide") end)
  elseif status2 >= 60 then
    spawn(function() self:AddEvent_1("Ending_Work") end)
  else
    spawn(function() self:AddEvent_1("Ending_Bad") end)
  end
end

function C:CallEnding()
  if not coroutine.isyieldable() then spawn(C.CallEnding, self) return end
  WindowManager:CleanAll()
  CursorManager:SetCursorShowHide(false)
  Object.Instantiate(self.endingBlue, GameObject.Find("MainPanel").transform)
end

function C:ObiActive(onoff)
  self.obi:SetActive(onoff)
end

function C:fetchNextActionHint()
  self.nextActionHint = NetaManager:fetchNextActionHint()
  CommandManager:AddHint(self.nextActionHint)
end

function C:getHintedChip(a)
  if not coroutine.isyieldable() then spawn(C.getHintedChip, self, a) return end
  local gotAct = self.nextActionHint:Find(function(hint) return hint.Item1 == a end)
  if gotAct == nil then
    self.isChipGetting.Value = false
    return
  end
  self.Aim.Value = NgoEx.SystemTextFromType("System_FindNeta", Settings.CurrentLanguage.Value)
  AudioManager:PlaySeByType("SE_tweet_change_top", false)
  self.isChipGetting.Value = true
  self.gotChipAlpha = gotAct.Item2
  WindowManager:NewWindow_2("Jine", true)
  UniTask.Delay(Constants.FAST, false, "Update", nil, false)
  NetaManager:GetChip(self.gotChipAlpha.alphaType, self.gotChipAlpha.level)
  self.nextActionHint:Remove(gotAct)
  spawn(function() self:CallNetaGet() end)
end

function C:CallNetaGet()
  if not coroutine.isyieldable() then spawn(C.CallNetaGet, self) return end
  self:AddEventQueue_1("SetJineSeparator")
  self:AddEventQueue_2(CONCAT(CONCAT(CONCAT("ChipGet_", TOSTR(self.gotChipAlpha.alphaType)), "_"), self.gotChipAlpha.level))
  self:AddEventQueue_1("ChipGet_Show")
  self:StartEvent()
end

function C:getChip(type, level)
  if not coroutine.isyieldable() then spawn(C.getChip, self, type, level) return end
  self.gotChipAlpha = NEW("AlphaLevel", 1, type, level)
  NetaManager:GetChip(self.gotChipAlpha.alphaType, self.gotChipAlpha.level)
  self:AddEventQueue_1("SetJineSeparator")
  self:AddEventQueue_2(CONCAT(CONCAT(CONCAT("ChipGet_", TOSTR(self.gotChipAlpha.alphaType)), "_"), self.gotChipAlpha.level))
  self:AddEventQueue_1("ChipGet_Show")
  self:AddEventQueue_1("BlurWatchingSp")
end

function C:AwakePsycheDiary()
  if self.psycheCount ~= 0 then
    if self.psycheCount >= 1 then
      self.PsycheNikki1:SetActive(true)
    end
    if self.psycheCount >= 2 then
      self.PsycheNikki2:SetActive(true)
    end
    if self.psycheCount >= 3 then
      self.PsycheNikki3:SetActive(true)
    end
    if self.psycheCount >= 4 then
      self.PsycheNikki4:SetActive(true)
    end
  end
end

function C:setLoveDiaryId(love)
  if love < 20 then
    self.loveDiary = 1
  elseif love < 40 then
    self.loveDiary = 2
  elseif love < 80 then
    self.loveDiary = 3
  else
    self.loveDiary = 4
  end
end

function C:AwakeLoveDiary()
  if self.loveDiary ~= 0 then
    if self.loveDiary == 1 then
      self.LoveNikki4:SetActive(true)
    elseif self.loveDiary == 2 then
      self.LoveNikki3:SetActive(true)
    elseif self.loveDiary == 3 then
      self.LoveNikki2:SetActive(true)
    elseif self.loveDiary == 4 then
      self.LoveNikki1:SetActive(true)
    end
  end
end

function C:TimePass()
  if self.nowEnding ~= "Ending_None" then
    return
  end
  if self.inNightBonus then
    GameObject.Find("Live"):GetComponent("CanvasGroup").interactable = true
    GameObject.Find("neru"):GetComponent("CanvasGroup").interactable = true
    GameObject.Find("Odekake"):GetComponent("CanvasGroup").interactable = true
  end
  if self.executingAction == "Error" then
    NotificationManager:AddTimePassingNotifier(1)
    return
  end
  if not self.isChipGetting.Value then
    NotificationManager:AddTimePassingNotifier(NgoEx.CmdFromType(self.executingAction).PassingTime)
    return
  end
  self.isChipGetting:Where(function(v) return not v end):Take(1):Subscribe(function(_)
    NotificationManager:AddTimePassingNotifier(NgoEx.CmdFromType(self.executingAction).PassingTime)
  end):AddTo(self.gameObject)
end

