end

function C:CleanPassingSaveData(savefile)
  local match = Regex.Match(savefile, "(?<=Data)\\d+")
  local match2 = Regex.Match(savefile, "(?<=Day)\\d+")
  local list = NEW("List", nil)
  do
    local i = Int32.Parse(match2.Value) + 1
    while i <= 30 do
      local text = ("Data" .. TOSTR(match.Value) .. "_Day" .. TOSTR(i) .. TOSTR(SaveRelayer.EXTENTION))
      if not SaveRelayer.IsSlotDataExists(text) then
        break
      end
      list:Add(text)
      i = i + 1
    end
  end
  SaveRelayer.DeleteDatas(list)
end

function C:SetShortcutState(isEnable, disabledAlpha)
  if isEnable then
    self.shortcuts.interactable = true
    self.shortcuts.blocksRaycasts = true
    self.shortcuts.alpha = 1
    if ControllerGuideManager ~= nil then
      ControllerGuideManager.IsReady = true
    end
  else
    self.shortcuts.interactable = false
    self.shortcuts.blocksRaycasts = false
    self.shortcuts.alpha = disabledAlpha
    if ControllerGuideManager ~= nil then
      ControllerGuideManager.IsReady = false
    end
  end
end

function C:HideShortcut()
  self.shortcuts.gameObject:SetActive(false)
  if ControllerGuideManager ~= nil then
    ControllerGuideManager.IsReady = false
  end
end

return C
